#include <bits/stdc++.h>
using namespace std;
#define MOD_CONST 1000000007
#define MAXNODES 33
#define LL long long
LL binArr[MAXNODES*2], nVal, mVal;

struct Mat {
    LL mat[MAXNODES][MAXNODES];
    inline Mat operator*(const Mat &b) const {
        Mat res;
        memset(res.mat, 0, sizeof(res.mat));
        for (int i=0; i<=mVal; ++i) {
            for (int j=0; j<=mVal; ++j) {
                for (int k=0; k<=mVal; ++k) {
                    res.mat[i][j]=(res.mat[i][j]+mat[i][k]*b.mat[k][j])%MOD_CONST;
                }
            }
        }
        return res;
    }
};

int getNumber() {
    int x=0, sign=1;
    char ch=getchar();
    while (ch<'0' || ch>'9') {
        if (ch=='-') sign=-1;
        ch=getchar();
    }
    while (ch>='0' && ch<='9') {
        x=x*10+ch-'0'; ch=getchar();
    }
    return x*sign;
}

int main() {
    nVal=getNumber(); mVal=getNumber();
    int tempN=nVal, len=-1;
    while (tempN) {
