        binArr[len]=tempN%mVal;
        tempN/=mVal;
    }
    len++;
    Mat answer, tempMat;
    memset(answer.mat, 0, sizeof(answer.mat));
    for (int i=0; i<=mVal; ++i) answer.mat[0][i]=1;
    static Mat P[MAXNODES*2], S[MAXNODES*2], A[MAXNODES*2];
    for (int i=0; i<=mVal; ++i) {
        for (int j=0; j<=mVal; ++j) {
