    for (int i=0; i<len; ++i) {
        for (int j=0; j<=mVal; ++j) {
            A[i][0].mat[j][j]=1;
        }
        if (i==0) {
            for (int j=0; j<mVal; ++j) {
                A[i][j].mat[mVal][mVal]=1;
                for (int k=0; k<mVal; ++k) {
                    if (k!=j) {
                        A[i][j].mat[k][k]=1;
                        for (int l=0; l<=mVal; ++l) A[i][j].mat[k][l]=1;
                    }
                }
            }
        } else {
            for (int j=0; j<mVal; ++j) {
                if (j==0) A[i][j]=S[i-1][0];
                else A[i][j]=S[i-1][j]*P[i-1][j-1];
            }
        }
        P[i][0]=A[i][0];
        for (int j=1; j<mVal; ++j) P[i][j]=P[i][j-1]*A[i][j];
        S[i][mVal-1]=A[i][mVal-1];
        for (int j=mVal-2; j>=0; --j) S[i][j]=A[i][j]*S[i][j+1];
    }
    int j=0;
    for (int i=len-1; i>=0; --i) {
        while (binArr[i]>0) {
            answer=answer*A[i][j]; j++; if (j==mVal) j=0; binArr[i]--;
